    #Node Vector Math
    @classmethod
    def vector_math(
        cls,
        base: Vector=None,
        vector: Vector=None,
        vector_1: Vector=None,
        multiplier: Vector=None,
        increment: Vector=None,
        incident: Vector=None,
        max: Vector=None,
        exponent: Vector=None,
        min: Vector=None,
        addend: Vector=None,
        vector_2: Vector=None,
        reference: Vector=None,
        scale: Float=None,
        ior: Float=None,
        operation: T_OPERATION_4='ADD'):
        """Node Vector Math.
        
        Jump: False

        Parameters
        ----------
        base : Vector, optional
            Socket 'Base', identifier 'Vector' (default: None)
        vector : Vector, optional
            Socket 'Vector', identifier 'Vector' (default: None)
        vector_1 : Vector, optional
            Socket 'Vector', identifier 'Vector_001' (default: None)
        multiplier : Vector, optional
            Socket 'Multiplier', identifier 'Vector_001' (default: None)
        increment : Vector, optional
            Socket 'Increment', identifier 'Vector_001' (default: None)
        incident : Vector, optional
            Socket 'Incident', identifier 'Vector_001' (default: None)
        max : Vector, optional
            Socket 'Max', identifier 'Vector_001' (default: None)
        exponent : Vector, optional
            Socket 'Exponent', identifier 'Vector_001' (default: None)
        min : Vector, optional
            Socket 'Min', identifier 'Vector_002' (default: None)
        addend : Vector, optional
            Socket 'Addend', identifier 'Vector_002' (default: None)
        vector_2 : Vector, optional
            Socket 'Vector', identifier 'Vector_002' (default: None)
        reference : Vector, optional
            Socket 'Reference', identifier 'Vector_002' (default: None)
        scale : Float, optional
            Socket 'Scale', identifier 'Scale' (default: None)
        ior : Float, optional
            Socket 'IOR', identifier 'Scale' (default: None)
        operation : {'ADD', 'SUBTRACT', 'MULTIPLY', 'DIVIDE', 'MULTIPLY_ADD', 'CROSS_PRODUCT', 'PROJECT', 'REFLECT', 'REFRACT', 'FACEFORWARD', 'DOT_PRODUCT', 'DISTANCE', 'LENGTH', 'SCALE', 'NORMALIZE', 'ABSOLUTE', 'POWER', 'SIGN', 'MINIMUM', 'MAXIMUM', 'ROUND', 'FLOOR', 'CEIL', 'FRACTION', 'MODULO', 'WRAP', 'SNAP', 'SINE', 'COSINE', 'TANGENT'}, optional
            Node parameter 'operation' (default: 'ADD')

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {}
        named_sockets['ID_Vector'] = None
        if base is not None: named_sockets['ID_Vector'] = base
        if vector is not None: named_sockets['ID_Vector'] = vector
        named_sockets['ID_Vector_001'] = None
        if vector_1 is not None: named_sockets['ID_Vector_001'] = vector_1
        if multiplier is not None: named_sockets['ID_Vector_001'] = multiplier
        if increment is not None: named_sockets['ID_Vector_001'] = increment
        if incident is not None: named_sockets['ID_Vector_001'] = incident
        if max is not None: named_sockets['ID_Vector_001'] = max
        if exponent is not None: named_sockets['ID_Vector_001'] = exponent
        named_sockets['ID_Vector_002'] = None
        if min is not None: named_sockets['ID_Vector_002'] = min
        if addend is not None: named_sockets['ID_Vector_002'] = addend
        if vector_2 is not None: named_sockets['ID_Vector_002'] = vector_2
        if reference is not None: named_sockets['ID_Vector_002'] = reference
        named_sockets['ID_Scale'] = None
        if scale is not None: named_sockets['ID_Scale'] = scale
        if ior is not None: named_sockets['ID_Scale'] = ior

        node = Node( 'Vector Math', named_sockets=named_sockets, operation=operation)
        return node._out

